files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #8a8a9a;
  --border: #0f3460;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: 'Courier New', Courier, monospace;
  font-size: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
  image-rendering: pixelated;
}

.card {
  background: var(--card);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 var(--border);
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.title {
  font-size: 1.5rem;
  letter-spacing: 2px;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--border);
}

.mode-indicator {
  font-size: 1.2rem;
  font-weight: bold;
  color: var(--accent);
  letter-spacing: 3px;
  text-transform: uppercase;
}

.timer {
  font-size: clamp(3rem, 20vw, 5rem);
  font-weight: bold;
  letter-spacing: 4px;
  color: var(--text);
  text-shadow: 4px 4px 0 var(--border);
  line-height: 1;
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  background: var(--accent);
  color: var(--text);
  border: 3px solid var(--border);
  box-shadow: 4px 4px 0 var(--border);
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: bold;
  padding: 12px 24px;
  cursor: pointer;
  letter-spacing: 1px;
  transition: transform 0.05s, box-shadow 0.05s;
  min-width: 120px;
}

.btn:hover {
  background: #ff5a7a;
}

.btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.btn:active {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 var(--border);
}

.btn.small {
  font-size: 0.9rem;
  padding: 8px 16px;
  min-width: 90px;
  background: var(--border);
}

.btn.small:hover {
  background: #1a4a7a;
}

.btn.small.active {
  background: var(--accent);
}

.mode-switch {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .btn {
    min-width: 100px;
    padding: 10px 16px;
  }
}

const WORK_TIME = 25 * 60;
const BREAK_TIME = 5 * 60;

let currentMode = 'work';
let timeLeft = WORK_TIME;
let timerInterval = null;
let isRunning = false;

const timerEl = document.getElementById('timer');
const modeIndicator = document.getElementById('modeIndicator');
const startPauseBtn = document.getElementById('startPauseBtn');
const resetBtn = document.getElementById('resetBtn');
const workBtn = document.getElementById('workBtn');
const breakBtn = document.getElementById('breakBtn');

function formatTime(seconds) {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
}

function updateDisplay() {
  timerEl.textContent = formatTime(timeLeft);
  modeIndicator.textContent = currentMode === 'work' ? 'WORK' : 'BREAK';
}

function setMode(mode) {
  currentMode = mode;
  timeLeft = mode === 'work' ? WORK_TIME : BREAK_TIME;
  stopTimer();
  updateDisplay();
  workBtn.classList.toggle('active', mode === 'work');
  breakBtn.classList.toggle('active', mode === 'break');
  workBtn.setAttribute('aria-pressed', mode === 'work');
  breakBtn.setAttribute('aria-pressed', mode === 'break');
}

function startTimer() {
  if (isRunning) return;
  isRunning = true;
  startPauseBtn.textContent = 'PAUSE';
  startPauseBtn.setAttribute('aria-label', 'Pause timer');
  timerInterval = setInterval(() => {
    timeLeft--;
    updateDisplay();
    if (timeLeft <= 0) {
      clearInterval(timerInterval);
      isRunning = false;
      startPauseBtn.textContent = 'START';
      startPauseBtn.setAttribute('aria-label', 'Start timer');
      timerEl.textContent = '00:00';
    }
  }, 1000);
}

function pauseTimer() {
  clearInterval(timerInterval);
  isRunning = false;
  startPauseBtn.textContent = 'START';
  startPauseBtn.setAttribute('aria-label', 'Start timer');
}

function stopTimer() {
  clearInterval(timerInterval);
  isRunning = false;
  startPauseBtn.textContent = 'START';
  startPauseBtn.setAttribute('aria-label', 'Start timer');
}

function resetTimer() {
  stopTimer();
  timeLeft = currentMode === 'work' ? WORK_TIME : BREAK_TIME;
  updateDisplay();
}

startPauseBtn.addEventListener('click', () => {
  if (isRunning) {
    pauseTimer();
  } else {
    startTimer();
  }
});

resetBtn.addEventListener('click', resetTimer);
workBtn.addEventListener('click', () => setMode('work'));
breakBtn.addEventListener('click', () => setMode('break'));

updateDisplay();
